<?php\n\nnamespace App\\Services;\n\nuse App\\Models\\ShopOrder;\nuse Illuminate\\Support\\Facades\\Http;\nuse Illuminate\\Support\\Facades\\Log;\n\nclass YookassaPaymentService\n{\n    protected array $settings;\n    protected string $shopId;\n    protected string $secretKey;\n    protected string $baseUrl = 'https://api.yookassa.ru/v3/';\n\n    public function __construct(array $settings)\n    {\n        $this->settings = $settings;\n        $mode = $this->settings['mode'] ?? 'test';\n        $this->shopId = $this->settings[\"shop_id_{\$mode}\"] ?? '';\n        $this->secretKey = $this->settings[\"secret_key_{\$mode}\"] ?? '';\n    }\n\n    public function initiatePayment(ShopOrder $order, float $amount): array\n    {\n        $returnUrl = config('app.frontend_url') . '/checkout?payment=return&order_id=' . $order->id;\n        $amountValue = number_format($amount, 2, '.', '');\n\n        $payload = [\n            'amount' => ['value' => $amountValue, 'currency' => $this->settings['currency'] ?? 'RUB'],\n            'capture' => true,\n            'description' => 'Оплата заказа №' . $order->order_number,\n            'confirmation' => ['type' => 'redirect', 'return_url' => $returnUrl],\n            'metadata' => ['order_id' => $order->id],\n        ];\n        \n        // Добавление чека, если включена фискализация\n        if (($this->settings['fiscalization_enabled'] ?? false) && !empty($order->items)) {\n            $payload['receipt'] = $this->prepareReceipt($order);\n        }\n\n        try {\n            $response = Http::timeout(30)\n                ->retry(2, 1000)\n                ->withHeaders([\n                    'Idempotence-Key' => uniqid('yk_', true),\n                    'Content-Type' => 'application/json',\n                ])\n                ->withBasicAuth($this->shopId, $this->secretKey)\n                ->post($this->baseUrl . 'payments', $payload);\n\n            $data = $response->json();\n\n            if ($response->successful() && isset($data['confirmation']['confirmation_url'])) {\n                return [\n                    'success' => true,\n                    'payment_url' => $data['confirmation']['confirmation_url'],\n                    'transaction_id' => $data['id'],\n                    'request_data' => $payload,\n                    'response_data' => $data,\n                ];\n            } else {\n                Log::error('Yookassa API error', ['response' => $data, 'request' => $payload]);\n                return [\n                    'success' => false,\n                    'message' => $data['description'] ?? 'Yookassa API error',\n                    'request_data' => $payload,\n                    'response_data' => $data,\n                ];\n            }\n        } catch (\\Exception $e) {\n            Log::error('Yookassa request exception', ['error' => $e->getMessage()]);\n            return ['success' => false, 'message' => $e->getMessage()];\n        }\n    }\n\n    protected function prepareReceipt(ShopOrder $order): array\n    {\n        $receipt = [\n            'customer' => [\n                'full_name' => $order->name,\n                'email' => $order->email,\n                'phone' => $order->phone,\n            ],\n            'items' => [],\n        ];\n\n        foreach ($order->items as $item) {\n            $receipt['items'][] = [\n                'description' => $item->name,\n                'quantity' => $item->pivot->quantity,\n                'amount' => [\n                    'value' => number_format($item->pivot->price, 2, '.', ''),\n                    'currency' => 'RUB',\n                ],\n                'vat_code' => $this->settings['vat_code'] ?? 1, // 1 - без НДС\n                'payment_mode' => $this->settings['item_payment_mode'] ?? 'full_prepayment',\n                'payment_subject' => $this->settings['item_payment_subject'] ?? 'commodity',\n            ];\n        }\n\n        if ($order->delivery_cost > 0) {\n            $receipt['items'][] = [\n                'description' => 'Доставка',\n                'quantity' => 1,\n                'amount' => [\n                    'value' => number_format($order->delivery_cost, 2, '.', ''),\n                    'currency' => 'RUB',\n                ],\n                'vat_code' => $this->settings['vat_code'] ?? 1,\n                'payment_mode' => $this->settings['delivery_payment_mode'] ?? 'full_prepayment',\n                'payment_subject' => $this->settings['delivery_payment_subject'] ?? 'service',\n            ];\n        }\n\n        return $receipt;\n    }\n}\n